var e={"29268u":`RoboKit — monte e simule um carro robô`,qvztjl:`RoboKit — início do tutorial`,s42iv2:`academe.com.br (abre em uma nova aba)`,"16us7mj":`Idioma`,ktdb8o:`Configurações`,"198kuu7":`Bancada 3D`,ia581p:`Animação`,j4z771:`Pausar`,wlqobg:`Pausar (Espaço)`,h23ysv:`Velocidade de reprodução`,r953rm:`Zoom`,"19blqjd":`Aproximar`,"110wpq2":`Afastar`,q5w460:`Vista`,bldqt5:`Vista explodida (E)`,"44cnpg":`Vista de perseguição: seguir o carro por trás (C)`,"13epjbk":`Mapa visto de cima da pista de testes`,j4zjee:`O obstáculo selecionado`,yq1vr3:`Do centro do obstáculo, a partir do centro da pista, onde o carro parte virado para o alto do mapa`,"19kd62s":`Personalizar a pista`,l1a70i:`Personalizar a pista: mover, girar e redimensionar os obstáculos`,"15n0apn":`Desfazer a última alteração (Ctrl+Z). Ctrl+Shift+Z a refaz`,j4uzpn:`A pista como veio, com o carro de volta à largada`,"84sbk0":`Deixar a pista como estava (Esc)`,"1oy9vz":`Usar esta pista: a vista 3D é reconstruída e a simulação continua`,ium5z9:`Como o programa do carro decide`,vq0gg8:`Fechar o fluxograma`,s2tc63:`Fechar (Esc)`,"13bjj4d":`Colocar o carro em Auto e vê-lo decidir`,gfubiu:`Como o programa decide: abrir o fluxograma`,"1gh0at8":`Etapas do tutorial`,"61nq88":`Etapas anteriores`,ga5x9q:`Próximas etapas`,"1v1ybkn":`Dirigir`,"9anomo":`Para frente (W / ↑)`,bbake2:`Virar à esquerda (A / ←)`,bfl95g:`Parar (Espaço)`,iseiwq:`Virar à direita (D / →)`,"4o292l":`Ré (S / ↓)`,"10qzszt":`Velocidade dos motores`,"2yhdcy":`Modo de condução`,"8m10x9":`Manual (1)`,"1ogxhr7":`Desviar de obstáculos (2)`,"1i3ygcv":`Desligar os motores (3)`,"1dlx0na":`Buzzer (B)`,isqcd9:`Ângulo do servo`,"29ulgm":`Saída serial`,"1l0xxoj":`Fechar`,"2r1h4p":`Conexão`,cwepyb:`Carregando…`,"10iu545":`O RoboKit precisa de JavaScript para funcionar.`,"120y7gz":`Criado por`,"1hpelzf":`Placa`,"1j2fqe6":`BANCADA`,"17d8vhd":`Etapa 1 · Separe as peças`,gqo5v1:`Simulador`,"1py6ulk":`Clique para inspecionar`,"1ms3o1u":`Distância`,"2w2xwg":`Velocidade`,n44ilu:`Modo`,"1d2vfr6":`Servo`,"152va0w":`Simulação pausada`,"11i7yk1":`Clique em um obstáculo para selecioná-lo.`,"1a4x3zw":`Tamanho`,"1kpdcfp":`Comprimento`,gfxz9b:`Largura`,s3robe:`Diâmetro`,"7puwki":`Altura`,kbxnhn:`Rotação`,"7nkn2r":`Posição, a partir da largada`,v1hcj2:`À frente`,"1vf2pel":`À direita`,"1xakelj":`Shift`,"1esrfu8":`passos de 5 cm, 15°`,yvgdmk:`Alt`,"1w55ans":`tamanho a partir do centro`,"1xzs12p":`mover ·`,"14bbmnu":`girar`,g7xa5b:`Pista · 3 × 3 m`,vmlwpb:`Desfazer`,"2zps2o":`Redefinir`,ew9em3:`Cancelar`,lewgh4:`Salvar`,"1vz8dhj":`Como o programa decide`,m76rx7:`Escolha uma caixa para ver o código dela`,"1hnif0x":`Fluxo do programa`,"11rknnz":`Ao vivo`,"540b06":`Auto`,"1fr6xqr":`Separe as peças`,"1wu7r43":`Manual`,ky4lc5:`Parar`,"152av8f":`Atuadores`,"1df7dln":`Buzzer`,pksfl2:`dirigir ·`,"1hrh82t":`Espaço`,"9zyeew":`parar ·`,jw8yab:`modo ·`,j4ckle:`buzzer ·`,kzo6rh:`perseguição`,mcpijf:`Monitor serial`,"1aeugy":`Limpar`,"1jgmzoq":`← Voltar`,c9ljxw:`etapas`,"1padbm0":`Próximo`,g6g542:`Voltar à etapa`,"1k7z1pa":`Esc`,dpexcn:`Especificações`,"8f4gnm":`Ir para a etapa`,qy3p54:`CONFIGURAÇÕES`,"12znfuf":`A etapa de condução se conecta a`,"17rhf7d":`Carro real (Wi-Fi do ESP32)`,dsq8ip:`Endereço do carro`,"1ihj7t4":`Tela e som`,oh792y:`Tocar o buzzer pelos alto-falantes`,"1bxmuya":`Mostrar o feixe ultrassônico`,"1gxdv01":`A câmera segue o carro`,"9mmtn3":`Reiniciar a simulação`,"1k6e5zv":`Aplicar`,"1iptqu5":`URL inválida “{url}”`,"12bfr2h":`A URL deve começar com ws:// ou wss://`,"1s22nop":`Conectando a {url}`,"1q17yrm":`Tentando de novo em {s} s`,hsi0bv:`Sem dados do carro`,ye8ewg:`Conectado`,"1puhp9v":`Conectando…`,y1y3f2:`Sem dados`,ci4tze:`Desconectado`,"1fmx9lv":`Erro de conexão`,"19wtqq3":`Conectado · {board}`,"1b4ym3j":`Simulador embutido`,bgnl0z:`Preparando os gráficos`,"39rjx0":`Pronto`,"1ruee97":`A bancada 3D não conseguiu iniciar. Ela precisa de WebGL: tente outro navegador ou ative a aceleração por hardware.`,xa5swu:`PISTA DE TESTES`,"18xfupg":`Dirija com os controles à direita`,khccvm:`Dirija com W A S D ou com os controles à direita`,vhwww6:`Etapa {n} · {title}`,"1i98668":`Montando o carro`,y9b5jm:`Dispondo as peças`,qzfxj5:`Mostrar a linha {n} na bancada`,pj86x7:`Mostrar isto na bancada`,"13bzcw5":`Copiado`,"8gdme8":`Selecione e copie`,s6g5lw:`Copiar`,"1bstp0v":`Lista de materiais`,"1g4j0cl":`Você vai precisar de`,"15cdqf0":`Ferramentas`,"1wrxvmg":`Faça isto`,"1x0ptmh":`Mapa de pinos · {board}`,"1go9otx":`Sketches`,zvnhd5:`Sketch`,t8quxl:`Baixar`,na9qmv:`Se algo der errado`,"5mau71":`Nota`,"1xh5jos":`{kicker} · Etapa {n} de {total}`,slbawy:`Próximo: {step} →`,"7rhhil":`Recomeçar ↺`,"1mtyvb1":`Etapa {n}: {step} · {done} / {total} marcados`,"4x1xaj":`Etapa {n}: {step}`,d2gue0:`Caixa de papelão`,"1xebpbq":`Bloco de madeira`,hi63vm:`Lata`,"14yz9o9":`Vaso de planta`,"1g6nbya":`Ele tem de ficar dentro das paredes.`,v23nvk:`O ponto de largada do carro tem de ficar livre.`,"1d1sqge":`O carro está ali.`,sjcnug:`Dois obstáculos não podem ocupar o mesmo lugar.`,"1rjq9tt":`Arraste um obstáculo para movê-lo. As alças quadradas mudam o tamanho e a redonda o gira.`,qaws2z:`A pista vista de cima. Clique em um obstáculo para selecioná-lo e arraste-o para movê-lo. Pelo teclado: Page Down e Page Up selecionam um obstáculo, as setas o movem e R o gira.`,km6rtw:`Obstáculo`,v6zgjh:`A pista como veio. Ao salvar, o carro volta à largada.`,"1bneya5":`Toda volta começa aqui`,"1gvmqkj":`Decisão`,"2wk0tb":`Ação`,ltbyq8:`sim`,r90oai:`não`,"10pfeta":`{file} · linhas {lines}`,"1mv69ab":`{file} · linha {lines}`,v5glvz:`sem eco`,"1y6bn7c":`esquerda {left} · direita {right}`,"17yvayv":`Caminho livre: seguindo em frente`,g8loky:`{reading} à frente · para abaixo de {stop} cm`,"1qpxp29":`Parar · LED aceso · bipe`,lman68:`obstáculo a {reading} · abaixo de {stop} cm`,"4e4gg4":`Recuou: olha em volta`,"1x1kke3":`a leitura não mudava havia {s} s`,"1pc4lzp":`Deu ré: olha de novo`,"11qad25":`os dois lados estavam apertados demais para virar`,dfsfd7:`Preso: recuando`,eic5lt:`leitura sem mudança por {s} s`,n7w5mt:`Sem espaço para virar: dando ré`,etina8:`{sides} · abaixo de {tight} cm`,crgp5w:`Olhando para a direita`,vto9jk:`lê {reading}`,"1xubspn":`Olhando para a esquerda`,"92dcjq":`direita {right} · esquerda lê {reading}`,cfs13v:`Há espaço para virar?`,h7zzeh:`{sides} · precisa de {tight} cm`,qlw2zr:`Virando à esquerda de novo`,"1fd6gkc":`Virando à direita de novo`,"1hj21ci":`bloqueado logo após uma curva: mesmo sentido`,"1jk1kpr":`Virando à esquerda`,u6ps9c:`Virando à direita`,"1uvg70v":`Auto está desligado`,"1bbdvwo":`Vista ao vivo: só o carro simulado`,"1fj8dwo":`ligue o Auto para ver o carro decidir`,"14g7i3l":`um carro real informa leituras, não a etapa da sua rotina`,"15nlm70":`Voltar à etapa {n} · {step}`,"1i8tm8j":`Montado <b>nesta etapa</b>`,rpu2qi:`Montado na <b>etapa {n} · {step}</b>`,"1b4o3fw":`Ir para a etapa {n} →`,y322vs:`Idioma: {name}`,bk85tv:`Reproduzir`,"1x4eyna":`{action} (Espaço)`,gpdo6z:`Use um endereço ws:// ou wss://, por ex. ws://192.168.4.1:81/`,"1iquufv":`Conecte-se primeiro à rede Wi-Fi do carro. Veja o README.md para o formato de mensagens que o firmware deve usar.`,njqkz2:`Digite uma URL de WebSocket, por ex. ws://192.168.4.1:81/`,nrzvmi:`Dirige um carro simulado em uma pista de testes, sem precisar de hardware.`,cegybp:`Peças`,wv4sck:`Preparação`,"7z3mbb":`Tudo para um rover de quatro rodas com uma “cabeça” ultrassônica que pode olhar em volta. Disponha as peças assim e marque uma por uma. Passe o mouse sobre uma linha para achá-la no tapete, ou clique em uma peça para ver os detalhes.`,"1x97es5":`Carregue as células 18650 em um carregador de Li-ion adequado antes de começar e use células protegidas: uma célula sem proteção pode fornecer dezenas de amperes em um curto-circuito.`,"13wu8qd":`Chassi de acrílico: chapa inferior, do meio e superior`,"9z9vwl":`Motores com redução TT (3–6 V, 1:48) com 8 suportes de acrílico em T, 8 parafusos M3 × 30 e porcas`,"1qr4ely":`Rodas, 65 mm`,cmzolq:`Módulo driver de dois motores L9110S`,"1qgfn27":`Arduino UNO R3 + Sensor Shield V5 + cabo USB`,"15cdntm":`ESP32 DevKit V1 (30 pinos) + placa de expansão + cabo USB`,mfnvxi:`Sensor ultrassônico HC-SR04 + seu suporte para servo e parafusos`,"15iavp3":`Micro servo SG90 com braços e parafusos`,"1allzrf":`Células Li-ion 18650 (protegidas) + suporte de 2 posições em série com fios`,xooybo:`Chave deslizante, LED vermelho de 10 mm, resistor de 220 Ω, buzzer ativo de 5 V`,"1csc29i":`Chave deslizante, LED vermelho de 10 mm, buzzer ativo de 5 V, transistor NPN (PN2222A ou S8050), resistores de 220 Ω, 2 × 1 kΩ e 2 kΩ`,"17dpcif":`Plugue DC tipo barril com bornes de parafuso, 5.5 × 2.1 mm`,bozwcy:`20 jumpers fêmea–fêmea de 15 cm; fio de ligação vermelho e preto; 16 espaçadores de latão M3 fêmea–fêmea (8 × 25 mm, 4 × 15 mm, 4 × 10 mm), 32 parafusos M3 × 6 mm, fita de espuma, tubo termorretrátil`,"5z6ae7":`Ferro de solda, solda`,"1xhh6dp":`fios dos motores, a chave, os fios do LED e do buzzer`,"11dguvz":`Chaves de fenda pequenas`,"1b1pnob":`Phillips para os parafusos M3, de fenda para os bornes do driver e do plugue`,"1ligzav":`Alicate de corte / desencapador`,"3pb5yx":`cortar e desencapar o fio de ligação e os jumpers`,"1avt53n":`Multímetro`,"1slxnnr":`verificar a polaridade antes de ligar a energia`,"100w2b7":`Carregador de Li-ion`,"64j96q":`para as células 18650`,"1heknmc":`Computador, Arduino IDE`,"1mo2nzj":`para enviar o código na etapa 9`,t9gk37:`Motores`,"15i6udf":`Montagem`,"1fofbt3":`Motores e rodas`,"15llile":`Cada motor TT é um pequeno motor DC que aciona uma caixa de redução de plástico 1:48. Os dois motores da esquerda e os dois da direita sempre giram juntos, como as esteiras de um tanque: o carro faz curvas girando os dois lados em velocidades diferentes.`,k5fimq:`O vermelho no terminal interno de cada motor é o que permite ligar vermelho com vermelho na etapa 4: o motor da frente e o de trás de um lado ficam de frente um para o outro, então seus terminais internos fazem o mesmo papel. Os terminais são finos e quebram se o fio for puxado, então prenda com fita cada par de fios ao seu motor. Os fios ficam em pé no centro para que a fenda longa da chapa do meio possa descer sobre eles na etapa 3.`,"7fte4n":`Chapa inferior`,rbcm1a:`Motores com redução TT`,sjfn38:`Suportes de motor de acrílico em T`,"732lu":`Parafusos M3 × 30 e porcas`,skq14t:`Rodas`,"1s4rmq":`Coloque os quatro motores na chapa inferior, em seus lugares, com os eixos para fora e as pontas dos motores para o centro. Solde dois fios de uns 15 cm em cada um: o vermelho no terminal mais perto do centro do carro, o preto no terminal mais perto da roda. Deixe os oito fios em pé juntos no centro da chapa.`,"1mrwedd":`Levante a chapa. Por baixo, empurre um suporte para cima pela fenda do lado de dentro de cada motor e outro no entalhe da borda da chapa, do lado de fora. Passe dois parafusos M3 × 30 pelo suporte, pela caixa de redução e pelo suporte, com as cabeças do lado da roda, e aperte uma porca em cada um.`,"13sq8kw":`Encaixe uma roda em cada eixo. O eixo tem duas faces planas que se encaixam no cubo, então a roda não pode patinar nele.`,"199dyzl":`Chapas`,qr73r6:`Empilhe as chapas`,kig8cy:`Os espaçadores de latão erguem a chapa do meio 25 mm acima da chapa inferior, livre das caixas de redução de 22 mm de altura, e dão à eletrônica um piso plano. Cada espaçador tem rosca nas duas pontas: um parafuso sobe pela chapa de baixo e outro desce pelo que ficar em cima.`,"1w8a39y":`O acrílico racha se você apertar demais, então basta ficar firme. Os chassis variam: se o seu não tem furo onde o controlador precisa, dois espaçadores e uma almofada de fita de espuma sob a outra ponta seguram bem uma placa.`,jcqip:`Chapa do meio`,u6l9bq:`Espaçadores de latão M3 × 25 mm`,"4cdagt":`Espaçadores de latão M3 × 10 mm (para o controlador)`,xaqs1y:`Espaçadores de latão M3 × 15 mm (para a chapa superior)`,"300byl":`Parafusos M3 × 6 mm`,tezznv:`Parafuse oito espaçadores de 25 mm na chapa inferior, quatro de cada lado, cada um com um parafuso colocado por baixo.`,"70hnlv":`Antes de colocar a chapa do meio, enquanto ainda dá para alcançar por baixo, fixe os quatro espaçadores de 10 mm sob os furos de fixação do controlador (segure a placa no lugar para ver quais furos da chapa coincidem) e os quatro espaçadores de 15 mm nos cantos da metade traseira, cada um com um parafuso por baixo.`,"1tynoxv":`Abaixe a chapa do meio sobre os espaçadores de 25 mm, passando os fios dos motores para cima pela fenda longa do centro enquanto ela desce, e parafuse-a.`,"1n5adbz":`Driver`,"1ri406w":`Instale o driver dos motores`,"5n5nar":`Um pino de microcontrolador não deve fornecer mais que uns 20 mA, mas um motor TT puxa algumas centenas de mA andando e mais de 1 A travado. O módulo L9110S tem duas pontes H que chaveiam a corrente da bateria pelos motores e podem invertê-la.`,"1uicxnj":`Qual parafuso de um borne recebe qual par ainda não importa: o teste de fiação da etapa 9 mostra se um lado gira ao contrário ou se uma roda gira contra a sua parceira. Deixe livre a barra de 6 pinos (B-IA, B-IB, GND, VCC, A-IA, A-IB): a alimentação entra na etapa 7 e os sinais na etapa 8. O L9110S aguenta 800 mA por canal, e cada canal aqui aciona dois motores: suficiente para dirigir normalmente, mas não mantenha as rodas travadas. Se os chips esquentarem, um módulo TB6612FNG (1.2 A por canal) é uma troca mais robusta.`,utkklb:`Almofada de fita de espuma dupla face`,syij08:`Cole o driver na chapa do meio com fita de espuma, na frente dos espaçadores do controlador e à esquerda do centro: a barra de 6 pinos voltada para a borda esquerda do carro e os bornes de parafuso voltados para o centro do carro.`,"15kkcap":`Dobre os fios para frente ao longo da chapa e leve-os até os bornes do driver. Torça juntos os dois fios vermelhos dos motores da esquerda e juntos os dois pretos, e parafuse os dois pares em MOTOR-A, o borne mais perto do controlador. Faça o mesmo com os fios dos motores da direita em MOTOR-B.`,"18rvg69":`Controlador`,ync8b9:`Instale o Arduino UNO`,"1u68uls":`Instale o ESP32`,ertyxs:`O Arduino UNO (ATmega328P, 16 MHz, lógica de 5 V) executa o seu sketch. Um Sensor Shield V5 encaixa por cima e dá a cada pino sua própria barra G / V / S (terra, 5 V e sinal), porque a barra de alimentação do UNO tem só um pino de 5 V para dividir entre o servo e o sensor.`,"1p7bu2t":`O ESP32 (dois núcleos, até 240 MHz, Wi-Fi e Bluetooth, lógica de 3.3 V) executa o seu sketch e deixa o RoboKit dirigir o carro real por Wi-Fi. A placa de expansão acrescenta um conector DC com regulador e uma barra G / V / S para cada pino.`,ii2aq7:`Os pinos do UNO são de 5 V, então o sensor e o servo ligam direto no shield.`,"1ghuj2z":`Os pinos do ESP32 trabalham a 3.3 V e não toleram 5 V, então a saída Echo do sensor ganha um divisor de tensão na etapa 8.`,t5ws5g:`ESP32 DevKit V1 (30 pinos)`,"1tu8qz5":`Placa de expansão ESP32 (30 pinos)`,"14w4gx0":`Parafuse o UNO nos quatro espaçadores de 10 mm atrás do driver, com os conectores USB e DC voltados para o lado esquerdo do carro.`,hw767j:`Encaixe o Sensor Shield V5 no UNO com cada pino no seu soquete. Deixe o jumper SEL no lugar, para que os pinos V do shield recebam 5 V do UNO, e não ligue nada no borne de parafuso do shield.`,"1opbgrl":`Parafuse a placa de expansão nos quatro espaçadores de 10 mm atrás do driver, com o conector DC voltado para o lado esquerdo do carro.`,"1xxnsy2":`Encaixe o DevKit nos dois soquetes de modo que cada nome de pino nele coincida com o nome impresso ao lado do soquete. Uma placa deslocada um pino põe a alimentação nos pinos errados.`,ua2sfx:`Coloque o jumper dos pinos V em 5 V, porque o servo, o HC-SR04 e o buzzer precisam de 5 V. As placas de expansão variam, então confira as marcações do jumper na sua.`,"1jzloyj":`Sensor`,"19ot7f3":`Cabeça do sensor`,jii9ss:`O HC-SR04 emite uma rajada ultrassônica de 40 kHz e cronometra o eco: distância em cm ≈ tempo do eco em µs ÷ 58. Ele mede de 2 cm a uns 4 m, dentro de um feixe de uns 15° de largura. Montado em um servo SG90, pode olhar para a esquerda e a direita antes de o carro virar.`,"1s5nsw8":`Para centralizar o servo, ligue-o na barra A5 do shield (marrom no G) e envie qualquer um dos sketches da etapa 9: ambos deixam a cabeça em 90°. Girar o eixo de saída à força pode espanar as engrenagens de plástico. Montado nesta posição, os pinos do sensor são GND, Echo, Trig, VCC da esquerda para a direita, vistos de frente.`,"3b6msg":`Para centralizar o servo, ligue-o na barra GPIO 23 (marrom no G, V em 5 V) e envie o firmware da etapa 9, cujo setup() chama servoWrite(90). Girar o eixo de saída à força pode espanar as engrenagens de plástico. Montado nesta posição, os pinos do sensor são GND, Echo, Trig, VCC da esquerda para a direita, vistos de frente.`,"2934zx":`Micro servo SG90, braço simples e parafusos`,"1o4q0ha":`Suporte de servo para o HC-SR04, com seus parafusos`,"87cfw2":`Sensor ultrassônico HC-SR04`,"1bhe6w2":`Segure o servo sobre o recorte retangular na frente da chapa do meio, com o eixo de saída para cima e na linha central do carro. Passe o conector para baixo pelo recorte, para trás por baixo da chapa e para cima pela pequena fenda atrás dele, e puxe o cabo até o conector ficar sobre a chapa ao lado do controlador. Depois abaixe o servo no recorte, com o cabo descendo pelo entalhe da ponta, empurre o cabo que sobrar para baixo da chapa, longe do eixo do motor, e parafuse as duas orelhas do servo na chapa.`,"7x26fs":`Centralize o servo, depois encaixe um braço simples no eixo, apontando para frente, e fixe-o com o parafuso do braço.`,"3f8bcm":`Parafuse o suporte no braço, em pé e voltado para a frente.`,"178kb38":`Parafuse o HC-SR04 na frente do suporte pelos dois furos de canto de uma borda longa, com essa borda embaixo e os pinos em cima: assim os fios saem para cima, longe do servo.`,"1jamndy":`Alimentação`,tboesy:`Duas células 18650 em série dão 7.4 V nominais (8.4 V cheias, uns 6 V descarregadas). A chave interrompe o fio + da bateria. Tudo se encontra em um plugue DC com bornes de parafuso: os dois fios da bateria entram nele, o plugue alimenta o UNO pelo conector DC, cujo regulador gera os 5 V da lógica, e mais dois fios dos mesmos bornes alimentam o driver dos motores. O driver não pode tirar energia dos pinos de 5 V do shield: eles vêm do pequeno regulador do UNO, que quatro motores sobrecarregariam. As peças que precisam de fios soldados os recebem na bancada, antes de ir para o carro: passe primeiro um pedaço de termorretrátil no fio e encolha-o sobre a solda depois.`,r69l9i:`Duas células 18650 em série dão 7.4 V nominais (8.4 V cheias, uns 6 V descarregadas). A chave interrompe o fio + da bateria. Tudo se encontra em um plugue DC com bornes de parafuso: os dois fios da bateria entram nele, o plugue alimenta a placa de expansão pelo conector DC, cujos reguladores geram os 5 V e 3.3 V da lógica, e mais dois fios dos mesmos bornes alimentam o driver dos motores. O driver não pode tirar energia dos pinos de 5 V da placa: eles vêm do seu pequeno regulador, que quatro motores sobrecarregariam. As peças que precisam de fios soldados os recebem na bancada, antes de ir para o carro: passe primeiro um pedaço de termorretrátil no fio e encolha-o sobre a solda depois.`,"175zcey":`Confira a polaridade duas vezes antes de colocar as células: o conector do UNO tem o positivo no centro, e o borne + do plugue é o seu pino central (confira com um multímetro). Recarregue quando o pack cair para uns 7 V, abaixo dos quais o regulador do UNO não consegue manter 5 V. Se nenhum LED acender, desligue na hora e verifique a fiação antes de tentar de novo. O LED e o buzzer ficam na bancada até a etapa 8.`,t60ux3:`Confira a polaridade duas vezes antes de colocar as células: a maioria das placas de expansão tem o positivo no centro, mas confira o símbolo ao lado do conector, e o borne + do plugue é o seu pino central (confira com um multímetro). Recarregue quando o pack cair para uns 7 V. Se nenhum LED acender, desligue na hora e verifique a fiação antes de tentar de novo. O LED e o buzzer ficam na bancada até a etapa 8.`,mvli44:`Chapa superior + 4 parafusos M3 × 6 mm`,"1dowjmo":`Suporte 2 × 18650 com fios, 2 células`,"83x4u2":`Chave deslizante`,"1in9b4e":`Plugue DC tipo barril com bornes de parafuso (centro +)`,l8wrh1:`LED vermelho de 10 mm + resistor de 220 Ω`,"24gtky":`Buzzer ativo de 5 V`,"14zuroc":`Buzzer ativo de 5 V, transistor NPN + resistor de 1 kΩ`,"1pgj6ai":`Fita de espuma, termorretrátil, 4 jumpers para cortar: 2 vermelhos, 2 pretos`,"1ewjpxi":`Fita de espuma, termorretrátil, 5 jumpers para cortar: 2 vermelhos, 2 pretos, 1 laranja`,y2bs3a:`Coloque a chapa superior sobre os quatro espaçadores de 15 mm e parafuse-a.`,anc24f:`Na bancada, corte o fio vermelho do suporte a uns 2 cm do suporte. Solde a ponta do suporte em um pino externo da chave, e 10 cm do pedaço cortado no pino do meio.`,"1mixan6":`Segure o suporte sobre a chapa superior, com os fios para a esquerda do carro. Passe o fio preto para baixo pelo furo da borda esquerda da chapa e leve-o para frente pela chapa do meio enquanto abaixa o suporte. Cole o suporte com duas tiras de fita de espuma, e a chave de lado na borda esquerda da chapa, com a alavanca para fora. Depois leve o fio vermelho para frente, saindo pelo canto dianteiro da chapa. Os dois fios devem terminar ao lado do conector DC do controlador.`,"1xim7b6":`Corte um jumper vermelho e um preto a 12.5 cm de uma ponta. Encaixe o soquete do pedaço vermelho comprido no pino VCC do driver e o do preto comprido no GND, e leve os dois para trás pela borda esquerda da chapa do meio até o conector.`,"1200i":`Corte um jumper vermelho e um preto a 11 cm de uma ponta. Encaixe o soquete do pedaço vermelho comprido no pino VCC do driver e o do preto comprido no GND, e leve os dois para trás pela borda esquerda da chapa do meio até o conector.`,"1nymzxl":`Desencape 5 mm das quatro pontas soltas. Parafuse as duas vermelhas sob o parafuso + do plugue e as duas pretas sob o −, depois encaixe o plugue no conector DC do UNO, girado para que o + fique em cima.`,f3jc5e:`Desencape 5 mm das quatro pontas soltas. Parafuse as duas vermelhas sob o parafuso + do plugue e as duas pretas sob o −, depois encaixe o plugue no conector DC da placa de expansão, girado para que o + fique em cima.`,hhvzfi:`Na bancada, solde o resistor de 220 Ω em série com a perna longa (+) do LED. Corte ao meio um jumper vermelho e um preto. Solde uma metade vermelha na ponta livre do resistor e uma metade preta na perna curta do LED.`,"1qz1083":`Dobre os dois pinos do buzzer. Solde a outra metade vermelha no + (o pino mais longo, marcado em cima) e a outra metade preta no −.`,"110bbxt":`Dobre os dois pinos do buzzer e solde a outra metade vermelha no + (o pino mais longo, marcado em cima). Solde o coletor do transistor no pino − e um resistor de 1 kΩ na sua base; depois meio jumper laranja no resistor e a outra metade preta no emissor. Encolha um só tubo sobre o transistor e o resistor. Confira qual perna é qual na folha de dados do seu transistor.`,"1avlub7":`Verifique que nenhuma solda exposta possa tocar outra e que a chave esteja desligada. Depois coloque as duas células no suporte, cada ponta + onde o suporte mostra +. Ligue por um instante: os LEDs de alimentação do controlador e do driver devem acender.`,k2hc2b:`Fiação`,s234wa:`Faça a fiação`,"1po8toc":`Cada sensor e atuador encaixa em uma barra G / V / S do shield, então todos compartilham o terra do UNO; o terra do driver vem da bateria, que é o mesmo terra através do conector DC. Os pinos são escolhidos pela posição de cada peça, então os fios saem em leque das barras sem se cruzar. Trabalhe nesta ordem, com a chave desligada: primeiro o LED, embaixo na ponta esquerda da barra, e os quatro fios do sensor por último, porque passam em arco por cima de todo o resto. Um jumper entra uma ponta de cada vez: encaixe bem um soquete no pino, dobre o fio e encaixe o outro. Passe o mouse sobre uma linha para ver o fio no modelo.`,"1ylwoyd":`Cada sensor e atuador encaixa em uma barra G / V / S da placa de expansão, então todos compartilham o terra do ESP32; o terra do driver vem da bateria, que é o mesmo terra através do conector DC. Os pinos são escolhidos pela posição de cada peça, então os fios saem em leque das barras sem se cruzar. Trabalhe nesta ordem, com a chave desligada: primeiro o LED, embaixo na ponta esquerda da barra, e os fios do sensor por último, porque passam em arco por cima de todo o resto. Um jumper entra uma ponta de cada vez: encaixe bem um soquete no pino, dobre o fio e encaixe o outro. Passe o mouse sobre uma linha para ver o fio no modelo.`,"10tvb2g":`D5 e D11 levam a velocidade de cada lado: são pinos PWM que continuam funcionando enquanto a biblioteca Servo roda (ela assume o Timer1, o que desliga o PWM em D9 e D10). D6 e D12 levam a direção. O servo e o buzzer usam A5 e A0 como pinos digitais comuns. Todos os pinos G estão ligados entre si, assim como todos os pinos V: o GND e o VCC do sensor podem ir nos mais próximos.`,it0an4:`O divisor de 1 kΩ / 2 kΩ transforma o pulso Echo de 5 V em 3.3 V (5 V × 2 ⁄ 3). Echo usa o GPIO 35, um dos pinos só de entrada (34–39): ler é tudo o que ele precisa fazer. O buzzer é alimentado pelo pino V de 5 V e o transistor o chaveia, porque 3.3 V fica abaixo do que um buzzer de 5 V precisa. As saídas evitam os GPIO 0, 2, 5, 12, 14 e 15, que são pinos de inicialização ou pulsam enquanto o ESP32 inicia. Todos os pinos G estão ligados entre si, assim como todos os pinos V.`,"16ffufp":`LED: cole-o perto do canto dianteiro esquerdo do controlador · vermelho → S · preto → G`,"55vkwv":`Driver A-IA / A-IB (esquerda)`,"1wr2rcy":`Driver B-IA / B-IB (direita)`,"12y58k1":`Cabo do servo (marrom G, vermelho V, laranja S)`,"1xjcvwz":`Buzzer: cole-o na frente da chapa superior · vermelho → S · preto → G`,"1h6hx3u":`HC-SR04 Trig → S · VCC → V · GND → G do D2`,zvbj2f:`HC-SR04 Echo`,"83uabx":`Buzzer: cole-o na frente da chapa superior · vermelho → V · laranja (base) → S · preto (emissor) → G`,"1eb7xia":`HC-SR04 Trig → S · VCC → V · GND → G do GPIO 34`,"1ig2p4r":`HC-SR04 Echo: corte o jumper a 4.5 cm de uma ponta · 1 kΩ entre os pedaços · 2 kΩ até 4.7 cm cortados da ponta de um jumper preto · pedaços curtos → S e G`,xoaiok:`Código`,"1if8prf":`Programação`,"1g03ums":`Envie o código`,"1bv2ey7":`Dois sketches. O teste de fiação passa por cada peça, uma de cada vez, para você ver que cada uma está ligada e que os dois lados giram no sentido certo. O desviador de obstáculos é o programa do carro: ele anda até algo estar a menos de 22 cm, olha à direita e à esquerda com a cabeça e vira para o lado com mais espaço.`,"8lzj5q":`Este firmware transforma o ESP32 em um ponto de acesso Wi-Fi. Ele executa os comandos que o RoboKit envia (condução, velocidade, modo, servo, LED e buzzer), para se eles deixarem de chegar e envia de volta a distância e o estado dos motores 10 vezes por segundo. No modo Auto ele desvia de obstáculos sozinho, com a mesma rotina que o simulador executa.`,saufbh:`Quando nada reflete o ping, o HC-SR04 mantém Echo em nível alto por uns 38 ms (o valor da folha de dados; alguns módulos mantêm mais). Isso passa do tempo limite de 30 ms, então pulseIn() retorna 0. O desviador conta isso como 400 cm, “livre”, e não como “encostado”. O feixe é estreito, então o carro pode prender em um canto que nunca viu: uma leitura que para de mudar enquanto as rodas empurram mostra que ele está preso. E quando ele é bloqueado de novo logo após uma curva, vira mais uma vez no mesmo sentido em vez de voltar: em um canto, senão, ele viraria à esquerda, à direita, à esquerda para sempre.`,"11hew0t":`ledcAttach() e ledcWrite(pin, duty) são a API do arduino-esp32 3.x; as chamadas antigas ledcSetup() e ledcAttachPin() da 2.x não compilam mais. O feixe do sensor é estreito, então no Auto o carro pode prender em um canto que nunca viu: uma leitura que para de mudar enquanto as rodas empurram mostra que ele está preso. E quando ele é bloqueado de novo logo após uma curva, vira mais uma vez no mesmo sentido em vez de voltar: em um canto, senão, ele viraria à esquerda, à direita, à esquerda para sempre.`,"3zk06m":`No Arduino IDE, escolha Tools → Board → Arduino UNO e a porta certa. Os dois sketches usam a biblioteca Servo, que vem com o IDE.`,j0z2nr:`Apoie o carro para que as quatro rodas fiquem fora da mesa. Envie o teste de fiação, ligue a bateria e abra o Serial Monitor a 115200 baud. Acompanhe cada linha numerada acontecer: LED e bipe, cabeça à direita, à esquerda e ao centro, depois cada lado para frente e para trás.`,"1dz2oap":`Corrija o que não bateu (veja a lista abaixo). Depois envie o desviador de obstáculos, tire o cabo USB, coloque o carro no chão e ligue: ele espera dois segundos e parte.`,"4czqhs":`Mude TURN_MS no sketch até cada curva ser cerca de um quarto de volta no seu piso.`,rgjhux:`No Arduino IDE, adicione https://espressif.github.io/arduino-esp32/package_esp32_index.json em File → Preferences → Additional boards manager URLs. Depois instale “esp32 by Espressif Systems” versão 3.x pelo Boards Manager e escolha ESP32 Dev Module.`,"118rr9r":`Pelo Library Manager, instale a versão mais recente de “WebSockets” de Markus Sattler e “ArduinoJson” versão 7 de Benoit Blanchon.`,nbb8bl:`Envie o código, depois apoie o carro para que as quatro rodas fiquem fora da mesa e ligue a bateria. Entre na rede Wi-Fi “RoboKit” (senha drive1234), vá para a etapa 10 e conecte em Configurações → Carro real (Wi-Fi do ESP32).`,srtywe:`Teste cada controle, um de cada vez: LED, buzzer, o controle deslizante do servo, depois W A S D. Se um lado girar no sentido errado, veja a lista abaixo. Depois coloque o carro no chão, teste o Auto e mude TURN_MS até cada curva ser cerca de um quarto de volta.`,sp50jr:`Nada acende quando você liga`,"1gg4m0p":`Desligue. Verifique se as células estão carregadas e na posição certa, se os fios vermelhos estão sob o parafuso + do plugue e se a chave está ligada entre o pino do meio e um pino externo.`,"9crnd5":`Um lado gira ao contrário no teste`,"1mf4jfi":`Troque os dois fios desse lado no borne de parafuso: MOTOR-A é o lado esquerdo, MOTOR-B o direito.`,"1gcvytv":`Uma roda gira contra a sua parceira`,"76bppn":`Troque os dois fios desse motor onde estão torcidos com os do outro motor.`,kakgt9:`A linha 3 gira as rodas da direita`,"95tfvz":`Os dois pares de jumpers estão trocados: A-IA / A-IB vão para D11 / D12, B-IA / B-IB para D5 / D6.`,"1yvpqg9":`A cabeça olha primeiro para a esquerda`,"3fc0ov":`Alguns servos giram ao contrário: troque 20 e 160 nos sketches.`,"1ymivbo":`A distância é sempre 0.0 cm`,"1wzcqly":`Nenhum eco volta. Verifique se Trig está no D4 e Echo no D3, e se o VCC e o GND do sensor estão em um pino V e um pino G. Ele também lê 0 quando não há nada a menos de uns 4 m.`,lg1f33:`O UNO reinicia quando os motores partem`,gp3cr0:`A tensão da bateria está caindo: recarregue as células. Um capacitor de 470–1000 µF entre V e G no shield (atenção à polaridade) ajuda a alimentação de 5 V a atravessar as quedas.`,"13n04wo":`O carro zumbe mas não gira no lugar`,y7q52i:`Girar arrasta os quatro pneus de lado e exige mais força que andar reto: aumente SPIN em direção a MAX_PWM e recarregue as células.`,hvphiw:`Ele puxa para um lado`,ittf4s:`Não há dois motores iguais. Diminua o lado mais rápido: para um carro que puxa para a direita, drive(CRUISE - 10, CRUISE).`,"19do8xl":`O envio para em “Connecting…”`,hn5crr:`Segure o botão BOOT do DevKit até o envio começar, e verifique se o cabo USB transmite dados, não só energia.`,"144ggw6":`O RoboKit não conecta`,"1wm6oj5":`Um lado gira ao contrário`,"1buhj6h":`Esquerda e direita estão trocadas`,"1s6olzj":`Os dois pares de jumpers estão trocados: A-IA / A-IB vão para GPIO 26 / 27, B-IA / B-IB para GPIO 33 / 25.`,svln7p:`No Auto, a cabeça olha primeiro para a esquerda`,"1ki0m9i":`Alguns servos giram ao contrário: troque 20 e 160 em autoStep().`,"6xg3a":`A distância é sempre 400 cm`,"7himiv":`Nenhum eco volta. Verifique se Trig está no GPIO 32, se Echo chega ao GPIO 35 pelo divisor e se o VCC do sensor está em um pino de 5 V. Ele também lê 400 quando não há nada a menos de uns 4 m.`,ksb87p:`O buzzer fica mudo`,"9czfii":`Confira as pernas do transistor com a folha de dados (a ordem muda entre os tipos) e se o + do buzzer está em um pino de 5 V.`,igpqu0:`O ESP32 reinicia quando os motores partem`,owaty5:`A tensão da bateria está caindo: recarregue as células. Um capacitor de 470–1000 µF entre um pino de 5 V e G (atenção à polaridade) ajuda a alimentação a atravessar as quedas.`,"1u5gnnb":`Girar arrasta os quatro pneus de lado e exige mais força que andar reto: aumente a velocidade e recarregue as células.`,uak3xr:`1 · Teste de fiação`,"1jz093b":`2 · Desviador de obstáculos`,"129dlzg":`Firmware`,ussxe7:`Simulação`,"17ssthc":`Dirija`,bmzqy4:`O carro simulado tem as mesmas peças que o seu. Dirija-o pela pista de testes e depois mude para Auto: ele executa a mesma rotina do sketch do desviador de obstáculos. Ele para e apita diante de um obstáculo, olha à direita e à esquerda, vira para o lado com mais espaço e dá ré quando está preso.`,"189d210":`O carro simulado responde aos mesmos comandos que o RoboKit envia ao seu ESP32, e o Auto executa a mesma rotina do firmware. Quando o seu carro estiver montado, mude para ele em Configurações → Carro real (Wi-Fi do ESP32).`,olmdkx:`Roda, 65 mm`,psly3z:`Tração`,vffqvh:`Um pneu de borracha em um aro de plástico. O cubo tem um encaixe com duas faces planas que entra no eixo de saída do motor TT, então a roda não pode patinar. Quando o carro gira no lugar os pneus arrastam de lado, então a aderência importa.`,jq4v4c:`Cubo`,mq93xq:`encaixe com duas faces planas para o eixo do motor TT`,"1cgpuek":`Distância por volta`,esl998:`≈ 20.4 cm (π × 6.5 cm)`,"11yszgp":`Motor com redução TT`,m5llum:`Um pequeno motor DC com escovas que aciona uma caixa de redução de plástico 1:48. Inverta a corrente e a roda gira ao contrário; reduza a tensão média com PWM e ela desacelera.`,"525amd":`Tensão`,"226us9":`Relação de redução`,jpnnsq:`≈ 200 rpm a 6 V, sem carga`,"1dw4k8q":`Corrente`,"1p9wnb6":`≈ 150 mA sem carga · até ≈ 1.5 A travado a 6 V`,cdauuh:`Torque de travamento`,"1gzxf67":`≈ 0.8 kg·cm a 6 V`,ign4wl:`Corpo`,mad9cv:`Eixo`,"14e36jb":`Ø 5.5 mm com duas faces planas a 3.7 mm uma da outra, saindo dos dois lados`,feutd2:`Fixação`,"183nrmx":`dois furos de Ø 3 mm a 17.5 mm um do outro, 20 mm atrás do eixo`,"108seeu":`Suporte de motor`,"1mquwkf":`Chassi`,"10qeeg1":`Uma peça de acrílico em forma de T. A haste sobe pela chapa inferior ao lado da caixa de redução e a cabeça fica por baixo, então não pode sair. Vai um de cada lado de um motor, e dois parafusos longos atravessam os dois suportes e os dois furos de fixação da caixa de redução.`,"1kk17cw":`Material`,"1me4wyg":`acrílico`,st0e1p:`Por motor`,"8uzq1j":`2 suportes · 2 × parafusos M3 × 30 + porcas`,"1am47c9":`Encaixe`,v6cwyh:`por baixo da chapa: o de dentro em uma fenda, o de fora em um entalhe da borda`,"723pu9":`Leva os quatro motores e os oito espaçadores da chapa do meio. Uma fenda e um entalhe na borda ao lado de cada motor recebem os dois suportes desse motor.`,"1n7meho":`Tamanho (este modelo)`,r4lxco:`O piso da eletrônica. A fenda longa no centro deixa os fios dos motores subirem por baixo, e o recorte retangular na frente segura o servo; o entalhe na ponta é para o cabo do servo.`,"11vqw8c":`25 mm acima da chapa inferior`,"1957t19":`Chapa superior`,"2ljc6y":`Uma chapa de meio comprimento na traseira que leva o pack de baterias, a chave e o buzzer acima da eletrônica.`,"1ytak7b":`1.5 cm acima da chapa do meio`,"1ey525v":`Espaçador de latão, M3`,"7je4w9":`Espaçadores hexagonais com rosca nas duas pontas. Mantêm as chapas separadas e erguem as placas de circuito do acrílico para que nada embaixo delas encoste.`,"1t2znv5":`Rosca`,i9dhsi:`M3, fêmea–fêmea`,"1cazjzs":`chapa inferior → do meio (livra os motores de 22 mm)`,rni6ay:`chapa do meio → superior`,"1dz3bjd":`placa do controlador`,"1erre2c":`Parafusos`,"7fsd49":`um M3 × 6 mm em cada ponta, 32 no total`,pmsrct:`Fios dos motores`,h0ivdz:`Um fio vermelho e um preto de cada motor: vermelho no terminal mais perto do centro do carro, preto no mais perto da roda. Os dois motores de cada lado são ligados em paralelo a um canal do driver, vermelho com vermelho e preto com preto, então sempre giram juntos.`,"148isqp":`uns 15 cm cada`,"88dh10":`Par esquerdo`,"1hr3y9w":`MOTOR-A`,"1gp3zrj":`Par direito`,"1il2rct":`MOTOR-B`,"4iibl6":`Um lado gira ao contrário?`,"1p9lbgb":`troque os dois pares no borne`,"2380z5":`Uma roda contra a parceira?`,h5sbfv:`troque os dois fios desse motor`,"19qn9l6":`Driver de motores L9110S`,"82whm4":`Eletrônica`,"12ibf8u":`Dois chips ponte H L9110S, um por canal. Cada canal tem duas entradas: IA em nível alto e IB em nível baixo gira o motor em um sentido, IA baixo e IB alto gira no outro, e as duas iguais o param. PWM em uma entrada define a velocidade.`,"25ul91":`Alimentação (VCC)`,m2phlf:`800 mA por canal (1.5–2 A de pico)`,"17s6ks8":`Entradas`,d0m2ee:`A-IA, A-IB, B-IA, B-IB · lógica de 3.3 V ou 5 V`,"4swwow":`Barra de pinos`,oja0mi:`B-IA · B-IB · GND · VCC · A-IA · A-IB (pinos em ângulo reto)`,"1xbblqt":`cerca de 29 × 23 mm, furos de fixação de Ø 3 mm (as medidas variam conforme o vendedor)`,"189a81e":`Uma placa com o microcontrolador ATmega328P. Ela executa o seu sketch, lê o sensor e decide o que os motores fazem.`,"1ebaepz":`ATmega328P a 16 MHz`,"16qkmtv":`Nível lógico`,eslzkd:`Pinos PWM`,oopaku:`Memória`,"8hfwsd":`32 KB de flash · 2 KB de RAM`,"1jzh7y5":`Entrada de alimentação`,"1vbs2jm":`7–12 V no conector DC (recomendado)`,"1hxwxrt":`Corrente por pino`,xms582:`20 mA recomendado · 40 mA máximo absoluto`,"1n28mf4":`Encaixa sobre o UNO e leva cada pino a uma barra de 3 pinos G / V / S (terra, 5 V, sinal), para que um servo ou sensor encaixe direto com seu próprio terra e alimentação.`,e8ir2h:`Barras de pinos`,d0uaj4:`D0–D13 e A0–A5, cada um G · V · S`,"1iy90zn":`Pinos V`,ohp32m:`5 V do UNO enquanto o jumper SEL estiver no lugar`,"1y4aysj":`Sem o jumper`,gi4ocs:`V vem do borne de parafuso do shield`,"1thlwjq":`Cuidado`,"1fzsig9":`nunca alimente o borne de parafuso com o SEL no lugar`,"1kft85q":`Extras`,"1e4238k":`Barras I²C e serial`,"1jeelmn":`ESP32 DevKit + placa de expansão`,"8jd2d6":`Um microcontrolador de dois núcleos com Wi-Fi e Bluetooth, encaixado em uma placa de expansão que acrescenta um conector DC com regulador e uma barra G / V / S para cada pino.`,"1inmx8d":`Módulo`,qx458t:`ESP32-WROOM-32 · até 240 MHz`,"7ra2ga":`3.3 V, não tolera 5 V`,"1chl2hi":`qualquer pino de saída (LEDC)`,"7fk3dd":`Sem fio`,"1b7zmuj":`Wi-Fi 802.11 b/g/n · Bluetooth`,pawwts:`≈ 6.5–12 V no conector DC (confira a sua placa)`,yzyhje:`3.3 V ou 5 V, definido por um jumper`,"7wntef":`Micro servo SG90`,mni0ct:`Um pequeno motor, caixa de redução e sensor de posição em uma única caixa. Ele espera um pulso a cada 20 ms (50 Hz); a largura do pulso define o ângulo: 1.5 ms é o centro, e cerca de 0.5–2.4 ms cobrem de 0° a 180°.`,wvoosj:`Torque`,"1e13gca":`≈ 0.1 s a cada 60°`,"1yo9wk7":`Tamanho · peso`,"1oaes5p":`23 × 12 × 29 mm · 9 g`,"1b34x3l":`Fios`,"1qalf36":`marrom GND · vermelho V+ · laranja sinal`,"1bshntj":`Suporte de servo do HC-SR04`,"1yr5sge":`Parafusa no braço do servo e segura o HC-SR04 por dois dos furos de canto, então o sensor gira com o servo e o feixe fica nivelado.`,"1t4m9bk":`Fixação`,mnle4w:`parafusos do braço do servo`,"1yzxd81":`Segura`,"1fp9bdu":`o HC-SR04 por dois dos furos de canto, sobre espaçadores`,"1yozvc2":`Outros tipos`,"16fhes5":`muitos suportes seguram o sensor pelos dois transdutores`,c8gdr7:`Um pulso de 10 µs em Trig faz um transdutor emitir oito ciclos de 40 kHz; o outro escuta. Echo então fica em nível alto pelo tempo que o som levou para ir e voltar, então cm = µs ÷ 58 (343 m/s, dividido por dois).`,"198uyr6":`Alcance`,"3xsn4q":`Feixe`,"1gw4v0v":`menos de 15°`,"1oy2zwu":`Alimentação`,"1m7niep":`Taxa de pings`,"7gsn1j":`um a cada 60 ms ou mais lento`,npm5w4:`Pinos (frente, esquerda → direita)`,pyp646:`VCC · Trig · Echo · GND com os pinos embaixo; montado com os pinos para cima, como aqui: GND · Echo · Trig · VCC`,cr1wqh:`Pack Li-ion 2 × 18650`,"1fdnj4z":`Duas células em série: 8.4 V cheias, 7.4 V nominais, uns 6 V descarregadas. Use células protegidas, nunca as coloque em curto e carregue-as em um carregador de Li-ion adequado.`,w63ube:`7.4 V nominais (6–8.4 V)`,serueh:`Capacidade`,"1lup9sh":`2000–3500 mAh (células originais)`,"7l22en":`Suporte`,"1ka7i4l":`2 posições, em série`,"1h1ba5m":`células protegidas são alguns mm mais longas; confira se cabem`,h4px5m:`Chave liga/desliga`,bs7ocz:`Interrompe o fio + da bateria, então o carro todo desliga. Ela é ligada entre o pino do meio e um pino externo: o fio vermelho do suporte em um, o fio para o plugue no outro. Fica de lado sobre fita de espuma na borda esquerda da chapa superior, com a alavanca para fora, onde um dedo alcança.`,"1m2zofh":`Tipo`,"69jc9h":`chave deslizante SPDT usada como liga/desliga`,w3vkqt:`Pinos`,"1owufyi":`três em linha: externo · comum · externo`,fph5dc:`Capacidade nominal`,"1bpycfc":`escolha uma de ≥ 2 A DC`,k3s7zg:`Buzzer ativo, 5 V`,"177ed2m":`Sinais`,jfbt4g:`Ele tem o próprio oscilador interno: ponha o pino em HIGH e ele apita em um tom fixo, sem precisar de código tone(). Ele consome até uns 25–30 mA: dentro do máximo absoluto de 40 mA do pino, mas acima dos 20 mA normalmente recomendados, então chaveá-lo com um transistor NPN é o hábito mais gentil.`,xscire:`Ele tem o próprio oscilador interno: alimente-o e ele apita em um tom fixo. Buzzers ativos de 5 V são especificados a partir de uns 3.5–4 V, então um pino de 3.3 V não consegue acioná-lo com confiança. Aqui ele é alimentado pelo pino V de 5 V e um transistor NPN, acionado pelo GPIO 21, o chaveia.`,"1p7q9i9":`Tom`,"17n9x61":`≈ 2.3 kHz`,z19kz7:`Tensão nominal`,"2tl42a":`5 V (funciona a partir de ≈ 3.5–4 V, conforme o fabricante)`,"1udh5u4":`≈ 25–30 mA a 5 V`,"1xat3vm":`a 7.6 mm um do outro`,"1yzktex":`Polaridade`,"1tmcwg9":`pino mais longo / “+” em cima = +`,i8lb7k:`LED vermelho de 10 mm`,"513nhj":`A corrente vai da perna longa (ânodo, +) para a curta (cátodo, −, junto à parte plana da borda). Ele sempre precisa de um resistor em série. Aqui ele fica de lado perto do canto dianteiro esquerdo do controlador, iluminando para a esquerda do carro.`,"17jikfo":`Tensão direta`,"1g61wql":`20 mA no máximo`,u532rf:`Resistor de 220 Ω`,"17qhgqf":`Limita a corrente do LED: (5 V − 2 V) ÷ 220 Ω ≈ 14 mA. As faixas de cor são vermelho, vermelho, marrom: 2, 2 e × 10 = 220 Ω.`,"1kwszon":`Limita a corrente do LED: (3.3 V − 2 V) ÷ 220 Ω ≈ 6 mA. As faixas de cor são vermelho, vermelho, marrom: 2, 2 e × 10 = 220 Ω.`,zzpczz:`Faixas`,"7ytjo4":`vermelho · vermelho · marrom · dourado`,"1llx3uw":`Tolerância`,"3389ey":`Divisor do Echo · 1 kΩ + 2 kΩ`,i8pnlw:`A saída Echo do HC-SR04 vai a 5 V, mas os pinos do ESP32 aceitam no máximo 3.3 V. Dois resistores em série do Echo ao terra formam um divisor: o GPIO lê a tensão no de 2 kΩ, 5 V × 2 kΩ ÷ (1 kΩ + 2 kΩ) ≈ 3.3 V.`,"15yc2v4":`Faixas de 1 kΩ`,"89urq0":`marrom · preto · vermelho · dourado`,"1ypqwgn":`Faixas de 2 kΩ`,"1ywrkmt":`vermelho · preto · vermelho · dourado`,"12k1o0e":`Echo → 1 kΩ → GPIO 35 · 2 kΩ do GPIO 35 ao G`,aarp77:`Necessário para`,"15e8vss":`só ESP32`,"1aqlq1n":`Transistor do buzzer · NPN + 1 kΩ`,vudz42:`Um transistor NPN funciona como chave: uma pequena corrente na base deixa passar uma maior do coletor ao emissor. O GPIO 21 aciona a base através de 1 kΩ, (3.3 V − 0.7 V) ÷ 1 kΩ ≈ 2.6 mA, mais que suficiente para chavear os ≈ 30 mA do buzzer a partir do pino de 5 V.`,"1gy1kba":`Transistor`,"62rwh2":`PN2222A, S8050 ou NPN parecido`,"1tlwyig":`Coletor`,"18vf2cp":`− do buzzer`,"19phq7s":`Base`,hrttng:`1 kΩ → S do GPIO 21`,"10ztoj1":`Emissor`,"1m0unsb":`G do GPIO 21`,"16l0jzg":`Pernas`,v4q23:`confira a pinagem na folha de dados`,gy95h:`Fio de ligação`,"170hkbj":`Fio flexível vermelho e preto para os fios dos motores. Corte no comprimento conforme avança.`,"19d4ccc":`Vermelho`,ch832v:`o terminal mais perto do centro do carro, em cada motor`,bxogn8:`Preto`,"1xdely8":`o terminal mais perto da roda`,"114bxvb":`Jumpers fêmea–fêmea`,tq3ghm:`Cabos Dupont com um soquete em cada ponta que encaixam em pinos de 2.54 mm. As entradas do driver e o sensor usam um jumper inteiro por pino. Cortado em dois, um jumper vira fios com soquete em uma só ponta: para as peças que são soldadas (o LED, o buzzer) e para a alimentação do driver, cujas outras pontas vão sob os parafusos do plugue.`,xe6ekx:`Passo`,terfe0:`15 cm (os de 20 cm também servem: deixam laços maiores)`,q9r4h7:`Usados inteiros`,"16oowgw":`8: quatro entradas do driver, quatro pinos do sensor`,"1rf1gzr":`7: quatro entradas do driver, três pinos do sensor`,onu7hf:`Cortados`,"38aacf":`4: um vermelho e um preto ao meio para os fios do LED e do buzzer, um vermelho e um preto a 12.5 cm de uma ponta para a alimentação do driver`,"3iidc0":`6: um vermelho e um preto ao meio para os fios do LED e do buzzer, um laranja ao meio para a base do transistor, um vermelho e um preto a 11 cm de uma ponta para a alimentação do driver, e o fio Echo do sensor para o divisor`,"14fe75h":`Jumpers · sensor ultrassônico`,f96u6l:`Quatro jumpers saindo da barra de pinos do sensor, que fica em cima, em arco de volta até o shield. Qualquer pino V e qualquer pino G servem para VCC e GND: os mais próximos são usados, então os quatro fios saem em leque lado a lado.`,tuihok:`Quatro fios saindo da barra de pinos do sensor, que fica em cima, em arco de volta até a placa de expansão. Echo é um sinal de 5 V, então passa por um divisor de 1 kΩ / 2 kΩ (soldado no jumper, sob termorretrátil) antes de chegar ao GPIO de 3.3 V.`,ftyyiy:`V do D4`,"1xuokt7":`Trig`,o3rtpx:`S do D4`,gi87tw:`Echo`,m5ulv4:`S do D3`,y9urxb:`G do D2`,"1n4125d":`V do GPIO 32 (em 5 V)`,p5iwlb:`S do GPIO 32`,"1aj3mnm":`1 kΩ → S do GPIO 35 · 2 kΩ dali até o seu G`,p0bbcd:`G do GPIO 34`,"1kn37ri":`Jumpers · driver dos motores`,oiporr:`As quatro entradas do driver. Cada par controla um lado do carro: IA leva a velocidade, em um pino PWM, e IB a direção.`,z48w8g:`As quatro entradas do driver, cada uma em um pino com PWM. Cada par controla um lado do carro.`,"11ubulz":`A-IA / A-IB (esquerda)`,jf4uze:`B-IA / B-IB (direita)`,"15oeqsr":`Cabo do servo`,wowqjs:`O próprio cabo de três fios do servo. Ele desce pelo recorte e sobe pela fenda ao lado, volta pela chapa ao lado do controlador e chega à barra traseira; o que sobra fica dobrado sob a chapa. O conector de 3 vias encaixa de uma vez em uma barra G / V / S: marrom no G.`,v89fad:`O próprio cabo de três fios do servo. Ele desce pelo recorte e sobe pela fenda ao lado, volta pela chapa ao lado do controlador e chega à barra traseira; o que sobra fica dobrado sob a chapa. O conector de 3 vias encaixa de uma vez em uma barra G / V / S: marrom no G. A fileira V precisa estar em 5 V.`,r6nyn:`Marrom`,"1u2gqme":`Laranja (sinal)`,"1qoi1mz":`S do A5`,ovg5ed:`S do GPIO 23`,"1uovlnp":`Fios do LED`,"1mffxae":`Meio jumper vermelho e meio preto, soldados ao LED com um soquete na outra ponta. O ânodo vai pelo resistor de 220 Ω a um pino de sinal; o cátodo vai ao terra.`,elp8sy:`Ânodo (via 220 Ω)`,k62hvj:`S do D13`,ilk009:`Cátodo`,k48vv7:`G do D13`,tbj8zu:`S do GPIO 13`,imqrdy:`G do GPIO 13`,"1indwkw":`Fios do buzzer`,"1c2cbqo":`Meio jumper vermelho e meio preto soldados aos pinos do buzzer. Ponha o fio + em HIGH para apitar.`,epsmo4:`O buzzer fica entre o pino V de 5 V e o transistor. Ponha o GPIO 21 em HIGH e o transistor liga o − do buzzer ao terra, então ele apita.`,"1rigupw":`S do A0`,"1yvwce0":`G do A0`,"1tndblu":`V do GPIO 21 (5 V)`,i73cl5:`coletor do transistor`,a4pty4:`Base (via 1 kΩ)`,obgy0f:`S do GPIO 21`,g663eg:`Fiação de alimentação`,wp3j1m:`Tudo se encontra em um plugue DC com dois bornes de parafuso, encaixado no conector DC do UNO. O + da bateria chega ao borne + pela chave; o − da bateria vai direto ao borne −. Um segundo fio vermelho e um segundo preto sob os mesmos dois parafusos levam a tensão da bateria aos pinos VCC e GND do driver. O driver não pode ser alimentado pelos pinos de 5 V do shield: eles vêm do regulador do UNO, que aguenta no máximo algumas centenas de mA.`,"1gazt2h":`Tudo se encontra em um plugue DC com dois bornes de parafuso, encaixado no conector DC da placa de expansão. O + da bateria chega ao borne + pela chave; o − da bateria vai direto ao borne −. Um segundo fio vermelho e um segundo preto sob os mesmos dois parafusos levam a tensão da bateria aos pinos VCC e GND do driver. O driver não pode ser alimentado pelos pinos de 5 V da placa: eles vêm do seu regulador, que aguenta no máximo algumas centenas de mA.`,"1wuyp3l":`+ da bateria (pela chave)`,"161fdmk":`− da bateria = GND`,"6j9255":`Plugue`,"1qkac6a":`barril de 5.5 × 2.1 mm, centro +, com bornes de parafuso`,"1s864ea":`Sob cada parafuso`,wj14kx:`dois fios: um da bateria, um para o driver`,oz5l6a:`Desviador de obstáculos`,zj0mwn:`Medir a distância`,"9jogsy":`A cada volta de loop(), o sensor dispara um ping. O sketch também anota quando a leitura mudou por último mais de {changeCm} cm: uma leitura que não muda enquanto as rodas empurram é como ele vai saber que o carro está preso.`,"1va2b8a":`Caminho livre?`,yssn5p:`O caminho está livre?`,zou1hc:`Livre significa nada a menos de {stopCm} cm (STOP_CM) e uma leitura que ainda está mudando. Então o carro segue em frente e pergunta de novo {pingMs} ms depois.`,"164owbk":`Seguir em frente`,"2guryp":`LED apagado, os dois lados para frente em CRUISE e uma espera de {pingMs} ms: o sensor precisa desse tempo entre dois pings. Depois, mais uma volta.`,l1vybm:`Parar
LED aceso · bipe`,ywa890:`Parar, LED aceso, um bipe curto`,"17krb65":`Bloqueado ou preso: os motores param, o LED acende e o buzzer toca por {beepMs} ms.`,"1njcbjw":`Preso?`,"6b9vj0":`Preso em algo que o feixe não viu?`,"12aymoo":`O feixe do sensor tem só uns 15° de largura, então o carro pode prender em um canto que nunca viu. Se a leitura não mudou mais de {changeCm} cm em {stuckMsS}, embora o caminho parecesse livre, o carro está preso. (Nenhum eco, 400, nunca conta: espaço aberto não é “preso”.)`,"7k6lib":`Recuar`,ooiwv8:`Ele se afasta do que o prende por {backOffMsS} e só então olha em volta.`,"1d4sv1w":`Olhar à direita, depois à esquerda`,"18crqcc":`A cabeça gira para {lookRight}° (direita) e para {lookLeft}° (esquerda). Em cada vez o servo recebe {settleMsS} para chegar antes de o sensor ser lido; as duas leituras são impressas.`,"1r9o4nf":`Há espaço para virar?`,"122yr22":`Se nenhum lado tem {tightCm} cm (TIGHT_CM), não há espaço para virar aqui.`,"1i7u6tc":`Dar ré, olhar de novo`,"1ik4v71":`Dar ré e olhar de novo`,a0a741:`Encurralado: ele dá ré por {backMsS} e olha de novo à direita e à esquerda dali, quantas vezes for preciso.`,"1yfjvg4":`Acabou de virar?`,"2jbjim":`Bloqueado de novo logo após uma curva?`,"3dv25u":`A cabeça volta para o centro. Então: se a última curva terminou há menos de {againMsS}, o carro mal se moveu desde que virou.`,"1steplx":`O mesmo sentido de novo`,kn4k3y:`Virar de novo no mesmo sentido`,"1k7wpmb":`Virar de volta só o levaria para onde estava: em um canto ele viraria à esquerda, à direita, à esquerda para sempre. Então ele continua virando no sentido em que virou por último, digam o que disserem as duas leituras.`,"1lf2d81":`O lado com mais espaço`,"1u19y2l":`Virar para o lado com mais espaço`,"1n1zre5":`Esquerda se a leitura da esquerda for pelo menos tão grande quanto a da direita; senão, direita.`,"5j8yhm":`Virar`,"4h9f4g":`Os dois lados giram em sentidos opostos por TURN_MS ({turnMs} ms, cerca de um quarto de volta: ajuste para o seu piso). Depois o carro para, lembra para que lado virou e quando, e loop() recomeça do topo.`,mz8bk9:`Modo Auto`,rg9t88:`Dez vezes por segundo loop() dispara um ping do sensor e guarda a leitura em distance (que vai para o RoboKit ao mesmo tempo). No modo Auto, autoStep() decide então o que fazer com ela.`,"15ai7e9":`Bloqueado significa algo a menos de {stopCm} cm (STOP_CM). A leitura pode ter até {sampleMsS} de idade, então logo após uma curva ele espera {freshMs} ms por uma feita já virado para a nova direção. Caso contrário, o carro continua andando.`,"1wwbbaz":`Enquanto anda, dir vale "forward": o fim de loop() transforma isso nas velocidades dos dois motores, na velocidade definida pelo RoboKit.`,q8ujdx:`O feixe do sensor tem só uns 15° de largura, então o carro pode prender em um canto que nunca viu. Se a leitura não mudou mais de {changeCm} cm em {stuckMsS} enquanto ele andava, o carro está preso: ele recua antes de olhar em volta. (Nenhum eco, 400, nunca conta: espaço aberto não é “preso”.)`,"1e83w8t":`A cabeça gira para {lookRight}° (direita), depois para {lookLeft}° (esquerda). Cada leitura é feita quando o servo já teve tempo de chegar, e a cabeça volta para o centro.`,"1pjappa":`Se a última curva terminou há menos de {againMsS}, o carro mal se moveu desde que virou. (Ligar o Auto recomeça do zero: turnedAt vale 0 então.)`,pjp20w:`Virar de volta só o levaria para onde estava: em um canto ele viraria à esquerda, à direita, à esquerda para sempre. Então goLeft fica como está e o carro vira no sentido em que virou por último, digam o que disserem as duas leituras.`,ihilws:`Os dois lados giram em sentidos opostos por TURN_MS ({turnMs} ms, cerca de um quarto de volta: ajuste para o seu piso). Depois o LED apaga, a hora é anotada e o carro volta a andar.`,"1k1y69x":`4× motor TT`,"15bpusl":`8× suporte de motor`,dgwrs0:`Parafusos, porcas e pinos M3`,"1mkf3n0":`4× roda, 65 mm`,"19aemsl":`Driver L9110S`,"123jzux":`almofada de espuma`,a4iz5j:`Placa de expansão ESP32`,"1al7iyf":`suporte do sensor`,a89ttz:`Servo SG90`,"1alynuo":`braço`,"1pbblc6":`Suporte 2 × 18650`,muur5i:`2× célula 18650`,"1t10ooq":`chave liga/desliga`,"7h9qib":`buzzer ativo`,"1uw5qdo":`plugue DC`,"1l9u4j2":`16× espaçador M3`,hiufn9:`fio de ligação`,"1w4hkux":`20× jumpers (F–F, 15 cm)`,"1onzquf":`chapa inferior`,"1h4bzq9":`chapa do meio`,myp2cd:`chapa superior`,pu413r:`Os navegadores bloqueiam ws:// a partir de uma página https:// — execute o RoboKit no seu computador (npm run dev) para chegar ao carro`,tqkecz:`Esta página é servida por https, por isso o navegador não a deixa abrir ws:// para o carro. Para conduzir o carro real, execute o RoboKit no seu computador (npm install e depois npm run dev) e abra http://localhost:5173.`,vqmrol:`O seu computador tem de estar na rede “RoboKit”, e o RoboKit tem de estar aberto por http://, não por https://: os navegadores bloqueiam ws:// a partir de páginas seguras, por isso uma cópia alojada na web não consegue chegar ao carro. Execute-o no seu computador (npm install enquanto ainda tem internet, depois npm run dev) e abra http://localhost:5173.`};export{e as default};